import 'dart:convert';

import 'package:analyzer/dart/element/element.dart';
import 'package:analyzer/dart/element/type.dart';

import 'component_reader.dart';

const generatedHeader =
    '// GENERATED CODE - DO NOT MODIFY BY HAND\n'
    '// Generated by styled_design_generator.\n\n'
    '// ignore_for_file: type=lint, unused_import, unnecessary_type_check, unnecessary_null_comparison, '
    'dead_null_aware_expression, invalid_null_aware_operator, unnecessary_non_null_assertion\n';

String _s(String v) =>
    "'${v.replaceAll(r'\', r'\\').replaceAll("'", r"\'").replaceAll(r'$', r'\$').replaceAll('\n', r'\n')}'";

/// The definition classes for the components of one library.
String writeDefinitions(List<ComponentPlan> components) {
  final b = StringBuffer();
  for (final c in components) {
    if (c.handWritten != null) continue;
    final props = <String, String>{};
    final slots = <String, String>{};
    final events = <String, String>{};
    for (final ctor in c.ctors) {
      for (final p in ctor.params) {
        if (p.propCode != null) props.putIfAbsent(p.entryName!, () => p.propCode!);
        if (p.slotCode != null) slots.putIfAbsent(p.entryName!, () => p.slotCode!);
        if (p.eventCode != null) events.putIfAbsent(p.entryName!, () => p.eventCode!);
      }
    }
    final named = [for (final ctor in c.ctors) ?ctor.name];
    final unnamed = c.ctors.where((ctor) => ctor.name == null).firstOrNull;

    String call(CtorPlan ctor) {
      final positional = [
        for (final p in ctor.params)
          if (p.positional) p.expression,
      ];
      final namedArgs = [
        for (final p in ctor.params)
          if (!p.positional) '${p.name}: ${p.expression}',
      ];
      final target = ctor.name == null ? '${c.type}${c.typeArgs}' : '${c.type}${c.typeArgs}.${ctor.name}';
      return '$target(${[...positional, ...namedArgs].join(', ')})';
    }

    b
      ..writeln()
      ..writeln('/// The design definition of [${c.type}].')
      ..writeln('final class ${c.definitionName} extends DesignDefinition {')
      ..writeln('  const ${c.definitionName}();')
      ..writeln()
      ..writeln('  @override')
      ..writeln('  DesignComponent get spec => const DesignComponent(')
      ..writeln('    type: ${_s(c.type)},');
    if (c.isValue) b.writeln('    kind: DesignKind.value,');
    b
      ..writeln('    category: ${_s(c.category)},')
      ..writeln('    summary: ${_s(c.summary)},');
    if (named.isNotEmpty) b.writeln('    constructors: [${named.map(_s).join(', ')}],');
    if (unnamed == null) b.writeln('    hasDefaultConstructor: false,');
    if (props.isNotEmpty) b.writeln('    props: [${props.values.join(', ')}],');
    if (slots.isNotEmpty) b.writeln('    slots: [${slots.values.join(', ')}],');
    if (events.isNotEmpty) b.writeln('    events: [${events.values.join(', ')}],');
    if (c.rules.isNotEmpty) b.writeln('    rules: [${c.rules.join(', ')}],');
    b
      ..writeln('  );')
      ..writeln()
      ..writeln('  @override');
    final fallback = unnamed ?? c.ctors.first;
    if (named.isEmpty) {
      b.writeln('  Object build(DesignBuildContext ctx) => ${call(fallback)};');
    } else {
      b.writeln('  Object build(DesignBuildContext ctx) => switch (ctx.constructor) {');
      for (final ctor in c.ctors.where((ctor) => ctor.name != null)) {
        b.writeln('    ${_s(ctor.name!)} => ${call(ctor)},');
      }
      b
        ..writeln('    _ => ${call(fallback)},')
        ..writeln('  };');
    }
    b.writeln('}');
  }
  return b.toString();
}

/// One preset family found in a library.
final class PresetFamilyPlan {
  final String family;
  final String variantEnum;
  final String libraryUri;
  final List<String> variants;
  final String? defaultVariant;
  final String? doc;

  /// Named arguments of `fromVariant` that take a token: name → token type.
  final Map<String, String> tokenArgs;

  const PresetFamilyPlan({
    required this.family,
    required this.variantEnum,
    required this.libraryUri,
    required this.variants,
    this.defaultVariant,
    this.doc,
    this.tokenArgs = const {},
  });

  Map<String, Object?> toJson() => {
    'family': family,
    'enum': variantEnum,
    'uri': libraryUri,
    'variants': variants,
    'default': defaultVariant,
    'doc': doc,
    'tokenArgs': tokenArgs,
  };

  factory PresetFamilyPlan.fromJson(Map<String, Object?> j) => PresetFamilyPlan(
    family: j['family']! as String,
    variantEnum: j['enum']! as String,
    libraryUri: j['uri']! as String,
    variants: (j['variants']! as List).cast<String>(),
    defaultVariant: j['default'] as String?,
    doc: j['doc'] as String?,
    tokenArgs: (j['tokenArgs'] as Map? ?? const {}).cast<String, String>(),
  );
}

/// The preset family [cls] declares, when it is a generated `@StyledPreset`
/// class: a StyleResolver with a `fromVariant(<Enum> variant, ...)` constructor.
PresetFamilyPlan? readPresetFamily(ClassElement cls) {
  final fromVariant = cls.getNamedConstructor('fromVariant');
  if (fromVariant == null || !cls.isPublic) return null;
  if (!cls.allSupertypes.any((t) => t.element.name == 'StyleResolver')) return null;
  final first = fromVariant.formalParameters.firstOrNull;
  final enumType = first?.type;
  if (first == null || !first.isPositional || enumType is! InterfaceType || enumType.element is! EnumElement) {
    return null;
  }
  final variants = [for (final c in (enumType.element as EnumElement).constants) c.name!];
  final source = cls.firstFragment.libraryFragment.source.contents.data;
  final defaultMatch = RegExp(
    '${RegExp.escape(cls.name!)}\\(\\s*(?:\\{[^}]*\\})?\\s*\\)\\s*:\\s*variant\\s*=\\s*${RegExp.escape(enumType.element.name!)}\\.(\\w+)',
  ).firstMatch(source);
  final tokenArgs = <String, String>{
    for (final p in fromVariant.formalParameters.skip(1))
      if (p.isNamed && p.type is InterfaceType && (p.type as InterfaceType).element.name == 'StyleValue')
        if ((p.type as InterfaceType).typeArguments.singleOrNull case final arg?)
          if (arg.isDartCoreDouble)
            p.name!: 'double'
          else if (arg is InterfaceType && arg.element.name == 'Color')
            p.name!: 'color',
  };
  final doc = cls.documentationComment
      ?.split('\n')
      .map((l) => l.replaceFirst(RegExp(r'^\s*///\s?'), ''))
      .takeWhile((l) => l.trim().isNotEmpty)
      .join(' ')
      .trim();
  return PresetFamilyPlan(
    family: cls.name!,
    variantEnum: enumType.element.name!,
    libraryUri: cls.library.uri.toString(),
    variants: variants,
    defaultVariant: defaultMatch?.group(1),
    doc: doc == null || doc.isEmpty ? null : doc,
    tokenArgs: tokenArgs,
  );
}

/// One definition the registry lists: its class and the library declaring it.
final class DefinitionRef {
  final String className;
  final String uri;
  const DefinitionRef(this.className, this.uri);

  Map<String, Object?> toJson() => {'class': className, 'uri': uri};
  factory DefinitionRef.fromJson(Map<String, Object?> j) => DefinitionRef(j['class']! as String, j['uri']! as String);
}

/// The package's `lib/design.g.dart`: every definition, preset factory and family.
String writeRegistry(List<DefinitionRef> definitions, List<PresetFamilyPlan> presets) {
  final uris = <String, String>{};
  String prefix(String uri) => uris.putIfAbsent(uri, () => 'i${uris.length}');
  definitions = [...definitions]..sort((a, b) => a.className.compareTo(b.className));
  presets = [...presets]..sort((a, b) => a.family.compareTo(b.family));
  final defs = [for (final d in definitions) '  ${prefix(d.uri)}.${d.className}(),'];
  final factories = <String>[];
  final families = <String>[];
  for (final p in presets) {
    final px = prefix(p.libraryUri);
    final args = [
      for (final MapEntry(key: name, value: type) in p.tokenArgs.entries)
        ", $name: a.token<${type == 'double' ? 'double' : 'Color'}>(${_s(name)})",
    ].join();
    factories.add(
      '  ${_s(p.family)}: (v, a) => $px.${p.family}.fromVariant($px.${p.variantEnum}.values.byName(v)$args),',
    );
    final argProps = [
      for (final MapEntry(key: name, value: type) in p.tokenArgs.entries)
        "DesignProp.token(${_s(name)}, tokenType: ${_s(type)})",
    ];
    families.add(
      '  ${_s(p.family)}: CatalogPresetFamily(name: ${_s(p.family)}, variants: [${p.variants.map(_s).join(', ')}]'
      '${p.defaultVariant != null ? ', defaultVariant: ${_s(p.defaultVariant!)}' : ''}'
      '${p.doc != null ? ', doc: ${_s(p.doc!)}' : ''}'
      '${argProps.isNotEmpty ? ', args: [${argProps.join(', ')}]' : ''}),',
    );
  }
  final b = StringBuffer(generatedHeader)
    ..writeln()
    ..writeln("import 'package:flutter/widgets.dart' show Color;")
    ..writeln("import 'package:styled_design/styled_design.dart';");
  for (final MapEntry(key: uri, value: px) in uris.entries) {
    b.writeln("import '$uri' as $px;");
  }
  b
    ..writeln()
    ..writeln('/// Every design definition this package declares.')
    ..writeln('const designDefinitions = <DesignDefinition>[')
    ..writeAll(defs.map((d) => '$d\n'))
    ..writeln('];')
    ..writeln()
    ..writeln('/// A factory per preset family, building a built-in variant by name.')
    ..writeln('final designPresets = <String, PresetFactory>{')
    ..writeAll(factories.map((f) => '$f\n'))
    ..writeln('};')
    ..writeln()
    ..writeln("/// Each preset family's variants, for the catalog.")
    ..writeln('const designPresetFamilies = <String, CatalogPresetFamily>{')
    ..writeAll(families.map((f) => '$f\n'))
    ..writeln('};');
  return b.toString();
}

String encodeIndex(List<DefinitionRef> definitions, List<PresetFamilyPlan> presets) => jsonEncode({
  'definitions': [for (final d in definitions) d.toJson()],
  'presets': [for (final p in presets) p.toJson()],
});
